1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Brick Breaker</title>
7	<style>
8	  html, body {
9	    margin: 0;
10	    padding: 0;
11	    height: 100%;
12	    background: radial-gradient(ellipse at center, #1b2440 0%, #0a0e1a 100%);
13	    color: #e8ecff;
14	    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
15	    overflow: hidden;
16	  }
17	  #wrap {
18	    display: flex;
19	    flex-direction: column;
20	    align-items: center;
21	    justify-content: center;
22	    height: 100%;
23	    gap: 10px;
24	  }
25	  canvas {
26	    display: block;
27	    background: #0d1226;
28	    border: 2px solid #3a4a8a;
29	    border-radius: 8px;
30	    box-shadow: 0 0 30px rgba(80, 120, 255, 0.35);
31	    max-width: 96vw;
32	    max-height: calc(96vh - 40px);
33	    aspect-ratio: 800 / 600;
34	    cursor: none;
35	    touch-action: none;
36	  }
37	  #help {
38	    font-size: 13px;
39	    color: #8f9bc8;
40	    user-select: none;
41	  }
42	</style>
43	</head>
44	<body>
45	<div id="wrap">
46	  <canvas id="game" width="800" height="600"></canvas>
47	  <div id="help">Arrows / A-D or mouse: move &nbsp;|&nbsp; Space / Click: launch &nbsp;|&nbsp; P: pause</div>
48	</div>
49	<script>
50	(function () {
51	  "use strict";
52	
53	  // ---------- Setup ----------
54	  var canvas = document.getElementById("game");
55	  var ctx = canvas.getContext("2d");
56	  var W = canvas.width;
57	  var H = canvas.height;
58	  var HUD_H = 44;
59	
60	  // ---------- Level definitions ----------
61	  // Characters: '.' = empty, '1'..'3' = brick with that many hits
62	  var LEVELS = [
63	    {
64	      name: "Level 1",
65	      ballSpeed: 380,
66	      maxSpeed: 520,
67	      layout: [
68	        "1111111111",
69	        "1111111111",
70	        "1111111111",
71	        "1111111111",
72	        "1111111111"
73	      ]
74	    },
75	    {
76	      name: "Level 2",
77	      ballSpeed: 450,
78	      maxSpeed: 640,
79	      layout: [
80	        "3.3333333.3",
81	        "22.22222.22",
82	        "222.222.222",
83	        "1111.1.1111",
84	        "21212.21212",
85	        "11111111111",
86	        "2.2.2.2.2.2"
87	      ]
88	    }
89	  ];
90	
91	  var ROW_COLORS = ["#ff5370", "#ff9a3c", "#ffd23f", "#5ce07a", "#3fc5ff", "#7c6cff", "#e36cff"];
92	  var HIT_COLORS = { 2: "#b8c2e8", 3: "#8892b8" };
93	
94	  // ---------- Game state ----------
95	  var STATE = {
96	    START: "start",
97	    SERVE: "serve",
98	    PLAY: "play",
99	    PAUSED: "paused",
100	    LEVEL_CLEAR: "levelclear",
101	    GAME_OVER: "gameover",
102	    WIN: "win"
103	  };
104	
105	  var state = STATE.START;
106	  var pausedFrom = null;
107	  var score = 0;
108	  var lives = 3;
109	  var levelIndex = 0;
110	  var bricks = [];
111	  var particles = [];
112	  var flashTimer = 0;
113	
114	  var paddle = {
115	    w: 110,
116	    h: 14,
117	    x: W / 2 - 55,
118	    y: H - 40,
119	    speed: 620
120	  };
121	
122	  var ball = {
123	    r: 8,
124	    x: W / 2,
125	    y: H - 50,
126	    vx: 0,
127	    vy: 0,
128	    speed: 380
129	  };
130	
131	  // ---------- Input ----------
132	  var keys = { left: false, right: false };
133	  var inputMode = "mouse"; // "mouse" or "keyboard"
134	  var mouseX = W / 2;
135	  var mouseActive = false;
136	
137	  function canvasMouseX(evt) {
138	    var rect = canvas.getBoundingClientRect();
139	    return (evt.clientX - rect.left) * (W / rect.width);
140	  }
141	
142	  window.addEventListener("keydown", function (e) {
143	    var k = e.key;
144	    var code = e.code;
145	    if (k === "ArrowLeft" || k === "a" || k === "A" || code === "KeyA") {
146	      keys.left = true;
147	      inputMode = "keyboard";
148	      e.preventDefault();
149	    } else if (k === "ArrowRight" || k === "d" || k === "D" || code === "KeyD") {
150	      keys.right = true;
151	      inputMode = "keyboard";
152	      e.preventDefault();
153	    } else if (code === "Space" || k === " ") {
154	      e.preventDefault();
155	      if (!e.repeat) primaryAction();
156	    } else if (k === "p" || k === "P" || code === "KeyP") {
157	      if (!e.repeat) togglePause();
158	    }
159	  });
160	
161	  window.addEventListener("keyup", function (e) {
162	    var k = e.key;
163	    var code = e.code;
164	    if (k === "ArrowLeft" || k === "a" || k === "A" || code === "KeyA") keys.left = false;
165	    if (k === "ArrowRight" || k === "d" || k === "D" || code === "KeyD") keys.right = false;
166	  });
167	
168	  canvas.addEventListener("mousemove", function (e) {
169	    mouseX = canvasMouseX(e);
170	    mouseActive = true;
171	    inputMode = "mouse";
172	  });
173	
174	  canvas.addEventListener("mouseleave", function () {
175	    mouseActive = false;
176	  });
177	
178	  canvas.addEventListener("mousedown", function (e) {
179	    e.preventDefault();
180	    mouseX = canvasMouseX(e);
181	    mouseActive = true;
182	    inputMode = "mouse";
183	    primaryAction();
184	  });
185	
186	  canvas.addEventListener("contextmenu", function (e) { e.preventDefault(); });
187	
188	  window.addEventListener("blur", function () {
189	    keys.left = keys.right = false;
190	    if (state === STATE.PLAY || state === STATE.SERVE) togglePause();
191	  });
192	
193	  function primaryAction() {
194	    switch (state) {
195	      case STATE.START:
196	        resetGame();
197	        break;
198	      case STATE.SERVE:
199	        launchBall();
200	        break;
201	      case STATE.PAUSED:
202	        togglePause();
203	        break;
204	      case STATE.LEVEL_CLEAR:
205	        loadLevel(levelIndex + 1);
206	        break;
207	      case STATE.GAME_OVER:
208	      case STATE.WIN:
209	        resetGame();
210	        break;
211	    }
212	  }
213	
214	  function togglePause() {
215	    if (state === STATE.PLAY || state === STATE.SERVE) {
216	      pausedFrom = state;
217	      state = STATE.PAUSED;
218	    } else if (state === STATE.PAUSED) {
219	      state = pausedFrom || STATE.PLAY;
220	      pausedFrom = null;
221	    }
222	  }
223	
224	  // ---------- Game flow ----------
225	  function resetGame() {
226	    score = 0;
227	    lives = 3;
228	    particles = [];
229	    loadLevel(0);
230	  }
231	
232	  function loadLevel(idx) {
233	    levelIndex = idx;
234	    var lvl = LEVELS[idx];
235	    bricks = [];
236	    var rows = lvl.layout.length;
237	    var cols = lvl.layout[0].length;
238	    var marginX = 30;
239	    var gap = 6;
240	    var top = HUD_H + 40;
241	    var bw = (W - marginX * 2 - gap * (cols - 1)) / cols;
242	    var bh = 22;
243	    for (var r = 0; r < rows; r++) {
244	      for (var c = 0; c < cols; c++) {
245	        var ch = lvl.layout[r].charAt(c);
246	        if (ch === "." || ch === "") continue;
247	        var hits = parseInt(ch, 10);
248	        if (!(hits > 0)) continue;
249	        bricks.push({
250	          x: marginX + c * (bw + gap),
251	          y: top + r * (bh + gap),
252	          w: bw,
253	          h: bh,
254	          hits: hits,
255	          maxHits: hits,
256	          row: r,
257	          alive: true
258	        });
259	      }
260	    }
261	    ball.speed = lvl.ballSpeed;
262	    paddle.x = W / 2 - paddle.w / 2;
263	    resetBallToPaddle();
264	    state = STATE.SERVE;
265	  }
266	
267	  function resetBallToPaddle() {
268	    ball.vx = 0;
269	    ball.vy = 0;
270	    ball.x = paddle.x + paddle.w / 2;
271	    ball.y = paddle.y - ball.r - 1;
272	    ball.speed = LEVELS[levelIndex].ballSpeed;
273	  }
274	
275	  function launchBall() {
276	    // Launch angle slightly randomized, mostly upward
277	    var angle = (Math.random() * 0.6 - 0.3); // radians from vertical
278	    ball.vx = ball.speed * Math.sin(angle);
279	    ball.vy = -ball.speed * Math.cos(angle);
280	    state = STATE.PLAY;
281	  }
282	
283	  function loseLife() {
284	    lives--;
285	    flashTimer = 0.35;
286	    if (lives <= 0) {
287	      lives = 0;
288	      state = STATE.GAME_OVER;
289	    } else {
290	      resetBallToPaddle();
291	      state = STATE.SERVE;
292	    }
293	  }
294	
295	  function levelCleared() {
296	    if (levelIndex + 1 < LEVELS.length) {
297	      state = STATE.LEVEL_CLEAR;
298	    } else {
299	      state = STATE.WIN;
300	    }
301	  }
302	
303	  // ---------- Physics helpers ----------
304	  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
305	
306	  // Keep ball direction from becoming too horizontal (prevents getting stuck
307	  // bouncing side-to-side) and keep magnitude equal to ball.speed.
308	  function normalizeVelocity() {
309	    var s = ball.speed;
310	    var len = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy) || 1;
311	    var vx = ball.vx / len;
312	    var vy = ball.vy / len;
313	    var minVy = 0.3; // ~17 degrees from horizontal at least
314	    if (Math.abs(vy) < minVy) {
315	      vy = (vy < 0 ? -1 : 1) * minVy;
316	      if (vy === 0) vy = -minVy;
317	      vx = (vx < 0 ? -1 : 1) * Math.sqrt(1 - minVy * minVy);
318	    }
319	    ball.vx = vx * s;
320	    ball.vy = vy * s;
321	  }
322	
323	  // Circle vs AABB. Returns null or {nx, ny, depth}
324	  function circleRect(cx, cy, r, rx, ry, rw, rh) {
325	    var px = clamp(cx, rx, rx + rw);
326	    var py = clamp(cy, ry, ry + rh);
327	    var dx = cx - px;
328	    var dy = cy - py;
329	    var d2 = dx * dx + dy * dy;
330	    if (d2 > r * r) return null;
331	    if (d2 > 1e-9) {
332	      var d = Math.sqrt(d2);
333	      return { nx: dx / d, ny: dy / d, depth: r - d };
334	    }
335	    // Center is inside the rectangle: push out along the axis of least penetration
336	    var left = cx - rx;
337	    var right = rx + rw - cx;
338	    var topD = cy - ry;
339	    var bottom = ry + rh - cy;
340	    var m = Math.min(left, right, topD, bottom);
341	    if (m === left) return { nx: -1, ny: 0, depth: left + r };
342	    if (m === right) return { nx: 1, ny: 0, depth: right + r };
343	    if (m === topD) return { nx: 0, ny: -1, depth: topD + r };
344	    return { nx: 0, ny: 1, depth: bottom + r };
345	  }
346	
347	  function hitBrick(b) {
348	    b.hits--;
349	    if (b.hits <= 0) {
350	      b.alive = false;
351	      score += 10 * b.maxHits + (levelIndex * 5);
352	      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, brickColor(b), 14);
353	    } else {
354	      score += 2;
355	      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, "#ffffff", 5);
356	    }
357	    // gentle speed-up
358	    ball.speed = Math.min(ball.speed + 4, LEVELS[levelIndex].maxSpeed);
359	  }
360	
361	  function stepBall(dt) {
362	    ball.x += ball.vx * dt;
363	    ball.y += ball.vy * dt;
364	
365	    // Walls
366	    if (ball.x - ball.r < 0) {
367	      ball.x = ball.r;
368	      ball.vx = Math.abs(ball.vx);
369	      normalizeVelocity();
370	    } else if (ball.x + ball.r > W) {
371	      ball.x = W - ball.r;
372	      ball.vx = -Math.abs(ball.vx);
373	      normalizeVelocity();
374	    }
375	    if (ball.y - ball.r < HUD_H) {
376	      ball.y = HUD_H + ball.r;
377	      ball.vy = Math.abs(ball.vy);
378	      normalizeVelocity();
379	    }
380	
381	    // Paddle
382	    if (ball.vy > 0) {
383	      var hit = circleRect(ball.x, ball.y, ball.r, paddle.x, paddle.y, paddle.w, paddle.h);
384	      if (hit) {
385	        if (ball.y <= paddle.y + paddle.h * 0.5) {
386	          // Top surface: angle depends on hit position
387	          var offset = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2 + ball.r);
388	          offset = clamp(offset, -1, 1);
389	          var maxAngle = 65 * Math.PI / 180;
390	          var angle = offset * maxAngle;
391	          ball.vx = ball.speed * Math.sin(angle);
392	          ball.vy = -ball.speed * Math.cos(angle);
393	          ball.y = paddle.y - ball.r - 0.5;
394	          normalizeVelocity();
395	        } else {
396	          // Side hit: deflect sideways, push out
397	          if (ball.x < paddle.x + paddle.w / 2) {
398	            ball.x = paddle.x - ball.r - 0.5;
399	            ball.vx = -Math.abs(ball.vx) - 1;
400	          } else {
401	            ball.x = paddle.x + paddle.w + ball.r + 0.5;
402	            ball.vx = Math.abs(ball.vx) + 1;
403	          }
404	          normalizeVelocity();
405	        }
406	      }
407	    }
408	
409	    // Bricks: resolve the deepest collision this substep (one per substep)
410	    var best = null;
411	    var bestHit = null;
412	    for (var i = 0; i < bricks.length; i++) {
413	      var b = bricks[i];
414	      if (!b.alive) continue;
415	      // cheap broad-phase
416	      if (ball.x + ball.r < b.x || ball.x - ball.r > b.x + b.w ||
417	          ball.y + ball.r < b.y || ball.y - ball.r > b.y + b.h) continue;
418	      var h = circleRect(ball.x, ball.y, ball.r, b.x, b.y, b.w, b.h);
419	      if (h && (!bestHit || h.depth > bestHit.depth)) {
420	        best = b;
421	        bestHit = h;
422	      }
423	    }
424	    if (best) {
425	      // Push out
426	      ball.x += bestHit.nx * bestHit.depth;
427	      ball.y += bestHit.ny * bestHit.depth;
428	      // Reflect only if moving into the surface
429	      var dot = ball.vx * bestHit.nx + ball.vy * bestHit.ny;
430	      if (dot < 0) {
431	        // Snap mostly-axis normals to the axis for cleaner bounces
432	        var nx = bestHit.nx, ny = bestHit.ny;
433	        if (Math.abs(nx) > 0.9) { nx = nx > 0 ? 1 : -1; ny = 0; }
434	        else if (Math.abs(ny) > 0.9) { ny = ny > 0 ? 1 : -1; nx = 0; }
435	        dot = ball.vx * nx + ball.vy * ny;
436	        ball.vx -= 2 * dot * nx;
437	        ball.vy -= 2 * dot * ny;
438	      }
439	      hitBrick(best);
440	      normalizeVelocity();
441	      if (countAlive() === 0) {
442	        levelCleared();
443	        return false;
444	      }
445	    }
446	
447	    // Bottom: lost ball
448	    if (ball.y - ball.r > H) {
449	      loseLife();
450	      return false;
451	    }
452	    return true;
453	  }
454	
455	  function countAlive() {
456	    var n = 0;
457	    for (var i = 0; i < bricks.length; i++) if (bricks[i].alive) n++;
458	    return n;
459	  }
460	
461	  // ---------- Particles ----------
462	  function spawnParticles(x, y, color, n) {
463	    for (var i = 0; i < n; i++) {
464	      var a = Math.random() * Math.PI * 2;
465	      var s = 60 + Math.random() * 200;
466	      particles.push({
467	        x: x, y: y,
468	        vx: Math.cos(a) * s,
469	        vy: Math.sin(a) * s,
470	        life: 0.4 + Math.random() * 0.4,
471	        max: 0.8,
472	        color: color
473	      });
474	    }
475	  }
476	
477	  function updateParticles(dt) {
478	    for (var i = particles.length - 1; i >= 0; i--) {
479	      var p = particles[i];
480	      p.life -= dt;
481	      if (p.life <= 0) { particles.splice(i, 1); continue; }
482	      p.vy += 400 * dt;
483	      p.x += p.vx * dt;
484	      p.y += p.vy * dt;
485	    }
486	  }
487	
488	  // ---------- Update ----------
489	  function updatePaddle(dt) {
490	    if (inputMode === "keyboard") {
491	      var dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
492	      paddle.x += dir * paddle.speed * dt;
493	    } else if (mouseActive) {
494	      paddle.x = mouseX - paddle.w / 2;
495	    }
496	    paddle.x = clamp(paddle.x, 0, W - paddle.w);
497	  }
498	
499	  function update(dt) {
500	    if (flashTimer > 0) flashTimer -= dt;
501	    updateParticles(dt);
502	
503	    if (state === STATE.SERVE) {
504	      updatePaddle(dt);
505	      ball.x = paddle.x + paddle.w / 2;
506	      ball.y = paddle.y - ball.r - 1;
507	    } else if (state === STATE.PLAY) {
508	      updatePaddle(dt);
509	      // Sub-step so the ball never moves more than ~1/3 of its radius per step (no tunneling)
510	      var dist = ball.speed * dt;
511	      var steps = Math.max(1, Math.ceil(dist / (ball.r / 3)));
512	      var sdt = dt / steps;
513	      for (var i = 0; i < steps; i++) {
514	        if (!stepBall(sdt)) break;
515	        if (state !== STATE.PLAY) break;
516	      }
517	    }
518	  }
519	
520	  // ---------- Rendering ----------
521	  function brickColor(b) {
522	    if (b.maxHits > 1 && b.hits > 1) return HIT_COLORS[b.hits] || "#9aa4cc";
523	    return ROW_COLORS[b.row % ROW_COLORS.length];
524	  }
525	
526	  function roundRect(x, y, w, h, r) {
527	    ctx.beginPath();
528	    ctx.moveTo(x + r, y);
529	    ctx.lineTo(x + w - r, y);
530	    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
531	    ctx.lineTo(x + w, y + h - r);
532	    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
533	    ctx.lineTo(x + r, y + h);
534	    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
535	    ctx.lineTo(x, y + r);
536	    ctx.quadraticCurveTo(x, y, x + r, y);
537	    ctx.closePath();
538	  }
539	
540	  function drawHUD() {
541	    ctx.fillStyle = "#141b38";
542	    ctx.fillRect(0, 0, W, HUD_H);
543	    ctx.fillStyle = "#3a4a8a";
544	    ctx.fillRect(0, HUD_H - 2, W, 2);
545	
546	    ctx.font = "bold 20px Segoe UI, Arial, sans-serif";
547	    ctx.textBaseline = "middle";
548	    ctx.fillStyle = "#e8ecff";
549	    ctx.textAlign = "left";
550	    ctx.fillText("Score: " + score, 16, HUD_H / 2);
551	
552	    ctx.textAlign = "center";
553	    ctx.fillStyle = "#ffd23f";
554	    ctx.fillText("Level " + (levelIndex + 1) + " / " + LEVELS.length, W / 2, HUD_H / 2);
555	
556	    ctx.textAlign = "right";
557	    ctx.fillStyle = "#e8ecff";
558	    var label = "Lives:";
559	    var startX = W - 16 - 3 * 22;
560	    ctx.fillText(label, startX - 8, HUD_H / 2);
561	    for (var i = 0; i < 3; i++) {
562	      ctx.beginPath();
563	      ctx.arc(startX + 11 + i * 22, HUD_H / 2, 7, 0, Math.PI * 2);
564	      ctx.fillStyle = i < lives ? "#ff5370" : "#39406a";
565	      ctx.fill();
566	    }
567	  }
568	
569	  function drawBricks() {
570	    for (var i = 0; i < bricks.length; i++) {
571	      var b = bricks[i];
572	      if (!b.alive) continue;
573	      var col = brickColor(b);
574	      roundRect(b.x, b.y, b.w, b.h, 4);
575	      ctx.fillStyle = col;
576	      ctx.fill();
577	      ctx.fillStyle = "rgba(255,255,255,0.25)";
578	      ctx.fillRect(b.x + 3, b.y + 3, b.w - 6, 4);
579	      if (b.maxHits > 1) {
580	        ctx.fillStyle = "#1a1f3a";
581	        ctx.font = "bold 13px Segoe UI, Arial, sans-serif";
582	        ctx.textAlign = "center";
583	        ctx.textBaseline = "middle";
584	        ctx.fillText(String(b.hits), b.x + b.w / 2, b.y + b.h / 2 + 1);
585	      }
586	    }
587	  }
588	
589	  function drawPaddle() {
590	    var grad = ctx.createLinearGradient(0, paddle.y, 0, paddle.y + paddle.h);
591	    grad.addColorStop(0, "#9fd8ff");
592	    grad.addColorStop(1, "#3f7bff");
593	    roundRect(paddle.x, paddle.y, paddle.w, paddle.h, 7);
594	    ctx.fillStyle = grad;
595	    ctx.fill();
596	  }
597	
598	  function drawBall() {
599	    ctx.beginPath();
600	    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
601	    ctx.fillStyle = "#ffffff";
602	    ctx.shadowColor = "#9fd8ff";
603	    ctx.shadowBlur = 12;
604	    ctx.fill();
605	    ctx.shadowBlur = 0;
606	  }
607	
608	  function drawParticles() {
609	    for (var i = 0; i < particles.length; i++) {
610	      var p = particles[i];
611	      ctx.globalAlpha = clamp(p.life / p.max, 0, 1);
612	      ctx.fillStyle = p.color;
613	      ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
614	    }
615	    ctx.globalAlpha = 1;
616	  }
617	
618	  function overlay(title, lines, titleColor) {
619	    ctx.fillStyle = "rgba(5, 8, 20, 0.72)";
620	    ctx.fillRect(0, HUD_H, W, H - HUD_H);
621	    ctx.textAlign = "center";
622	    ctx.textBaseline = "middle";
623	    ctx.fillStyle = titleColor || "#ffffff";
624	    ctx.font = "bold 52px Segoe UI, Arial, sans-serif";
625	    ctx.fillText(title, W / 2, H / 2 - 70);
626	    ctx.font = "20px Segoe UI, Arial, sans-serif";
627	    ctx.fillStyle = "#cfd6ff";
628	    for (var i = 0; i < lines.length; i++) {
629	      ctx.fillText(lines[i], W / 2, H / 2 - 10 + i * 30);
630	    }
631	  }
632	
633	  function render() {
634	    ctx.clearRect(0, 0, W, H);
635	    ctx.fillStyle = "#0d1226";
636	    ctx.fillRect(0, 0, W, H);
637	
638	    if (flashTimer > 0) {
639	      ctx.fillStyle = "rgba(255, 60, 90, " + (flashTimer * 0.6) + ")";
640	      ctx.fillRect(0, 0, W, H);
641	    }
642	
643	    drawHUD();
644	    drawBricks();
645	    drawParticles();
646	    drawPaddle();
647	    if (state !== STATE.GAME_OVER && state !== STATE.START) drawBall();
648	
649	    switch (state) {
650	      case STATE.START:
651	        overlay("BRICK BREAKER", [
652	          "Move: Left/Right arrows, A/D, or the mouse",
653	          "Launch: Space or mouse click",
654	          "Pause: P",
655	          "Break all bricks in 2 levels. You have 3 lives.",
656	          "",
657	          "Press Space or click to start"
658	        ], "#3fc5ff");
659	        break;
660	      case STATE.SERVE:
661	        ctx.textAlign = "center";
662	        ctx.textBaseline = "middle";
663	        ctx.font = "18px Segoe UI, Arial, sans-serif";
664	        ctx.fillStyle = "#cfd6ff";
665	        ctx.fillText("Press Space or click to launch", W / 2, H - 90);
666	        break;
667	      case STATE.PAUSED:
668	        overlay("PAUSED", ["Press P (or Space / click) to resume"], "#ffd23f");
669	        break;
670	      case STATE.LEVEL_CLEAR:
671	        overlay("LEVEL " + (levelIndex + 1) + " CLEAR!", [
672	          "Score: " + score,
673	          "Next: Level " + (levelIndex + 2) + " - tougher bricks, faster ball",
674	          "",
675	          "Press Space or click to continue"
676	        ], "#5ce07a");
677	        break;
678	      case STATE.GAME_OVER:
679	        overlay("GAME OVER", [
680	          "Final score: " + score,
681	          "",
682	          "Press Space or click to restart"
683	        ], "#ff5370");
684	        break;
685	      case STATE.WIN:
686	        overlay("YOU WIN!", [
687	          "All levels cleared!",
688	          "Final score: " + score + "  |  Lives left: " + lives,
689	          "",
690	          "Press Space or click to play again"
691	        ], "#ffd23f");
692	        break;
693	    }
694	  }
695	
696	  // ---------- Main loop ----------
697	  var lastTime = null;
698	  function frame(now) {
699	    if (lastTime === null) lastTime = now;
700	    var dt = (now - lastTime) / 1000;
701	    lastTime = now;
702	    if (dt > 0.05) dt = 0.05; // clamp large gaps (tab switches etc.)
703	    if (dt < 0) dt = 0;
704	    update(dt);
705	    render();
706	    requestAnimationFrame(frame);
707	  }
708	
709	  // Initialize level 1 layout for the start screen backdrop
710	  loadLevel(0);
711	  state = STATE.START;
712	  requestAnimationFrame(frame);
713	})();
714	</script>
